  "FORM": "FORME",
  "Rüstung: Panzerplatte (Verteidigung), Polsterung (Lebenspunkte) und Rune (Element-Schutz).": "Armure : plaque d'armure (défense), rembourrage (points de vie) et rune (protection élémentaire).",
  "Helm: Panzerplatte (Verteidigung), Polsterung (Lebenspunkte) und Rune (Element-Schutz).": "Casque : plaque d'armure (défense), rembourrage (points de vie) et rune (protection élémentaire).",
