  "Dein Brutnest ist voll – mehr als {n} Eier passen nicht hinein.": "Ton nid est plein – il ne peut pas contenir plus de {n} œufs.",
  "{egg}! Pflege es im Brutnest, dann schlüpft es.": "{egg}! Prends-en soin au nid et il éclora.",
  "aus der Zucht": "issu de l'élevage",
