  "{stage} · LV {lv} · Neu: {what} und eine neue Farbe": "{stage} · LV {lv} · Nouveau : {what} et une nouvelle couleur",
  "LV {lv}": "LV {lv}",
  "{name} erreicht LV {lv}!": "{name} atteint le LV {lv}!",
