  "Begleiter-Ausrüstung: {n} ({r})": "Équipement de compagnon : {n} ({r})",
  "BEGLEITER-EI!": "ŒUF DE COMPAGNON!",
  "{egg}! Bring es ins Brutnest im Versteck.": "{egg}! Apporte-le au nid du repaire.",
  "Ein Begleiter-Ei! Dein Brutnest ist voll – dafür +1 Glücksmünze.": "Un œuf de compagnon! Ton nid est plein – à la place, +1 pièce de Fortune.",
  "SCHILD": "BOUCLIER",
  "Nestmutter Gunda": "Gunda la Couveuse",
  "Wärme, Futter, Zuwendung. Fehlt eins davon, schläft das Küken im Ei einfach weiter.": "Chaleur, nourriture, affection. S'il en manque une seule, le poussin continue tout simplement de dormir dans son œuf.",
  "Sind alle drei Bedürfnisse gut gefüllt, wächst ein Ei anderthalbmal so schnell.": "Quand les trois besoins sont bien comblés, un œuf grandit une fois et demie plus vite.",
  "Streichle die Eier ruhig. Die spüren das. Wirklich.": "N'hésite pas à caresser les œufs. Ils le sentent. Vraiment.",
  "Aus einem schmutzigen Ei schlüpft meist eine Schnecke. Aber man liebt sie trotzdem.": "D'un œuf crasseux sort le plus souvent un escargot. Mais on l'aime quand même.",
  "Ein mythisches Ei braucht Tage. Und Sternenstaub. Und Geduld. Vor allem Geduld.": "Un œuf mythique demande des jours. Et de la poussière d'étoile. Et de la patience. Surtout de la patience.",
  "Brutnest: Ein Ei ist bereit zum Schlüpfen!": "Nid : un œuf est prêt à éclore!",
  "Brutnest: {n} Eier sind bereit zum Schlüpfen!": "Nid : {n} œufs sont prêts à éclore!",
  "Brutnest: Ein Ei braucht dich – es wächst gerade nicht.": "Nid : un œuf a besoin de toi – il ne grandit plus.",
  "Brutnest: {n} Eier brauchen dich – sie wachsen gerade nicht.": "Nid : {n} œufs ont besoin de toi – ils ne grandissent plus.",
  "BEREIT": "PRÊT",
  "Ein Ei! Das hast du dem Boss abgenommen? Bring es zu mir ins Brutnest – ich wohne jetzt im Versteck.": "Un œuf! Tu l'as pris à ce boss? Apporte-le-moi au nid – j'habite au repaire maintenant.",
  "Ein Ei! Wo hast du das denn gefunden? Bring es zu mir ins Brutnest – ich wohne jetzt im Versteck.": "Un œuf! Où l'as-tu donc trouvé? Apporte-le-moi au nid – j'habite au repaire maintenant.",
  "Halt es warm, füttere es und schenk ihm Zuwendung. Dann wächst es – auch während du unterwegs bist.": "Garde-le au chaud, nourris-le et donne-lui de l'affection. Alors il grandira – même pendant que tu es en route.",
  "Irgendwann schlüpft daraus dein erster Begleiter. Komm, ich zeig dir das Nest.": "Un jour, ton premier compagnon en sortira. Viens, je vais te montrer le nid.",
  "Ich bin Gunda und kümmere mich ab jetzt um das Brutnest im Versteck.": "Je suis Gunda, et désormais je m'occupe du nid au repaire.",
  "Eier schlüpfen nicht mehr von allein: Halt sie warm, füttere sie und schenk ihnen Zuwendung. Dann wachsen sie, auch während du unterwegs bist.": "Les œufs n'éclosent plus tout seuls : garde-les au chaud, nourris-les et donne-leur de l'affection. Alors ils grandiront, même pendant que tu es en route.",
  "DEIN ERSTES EI": "TON PREMIER ŒUF",
  "NEU: DAS BRUTNEST": "NOUVEAU : LE NID",
  "+{v} Schaden": "+{v} de dégâts",
