  "{name} fürchtet nur eines: {fear}.": "{name} ne craint qu'une chose : {fear}.",
  "Alte Lieder erzählen, {name} sei aus {origin} geboren.": "Selon d'anciens chants, {name} a jailli {origin}.",
  "Auf {name} steht ein Kopfgeld von {g} Gold. Niemand hat es je abgeholt.": "Une prime de {g} pièces d'or est promise pour {name}. Personne ne l'a jamais touchée.",
  "Die Karten des Ordens nennen {place} nur „das Revier von {name}“.": "Sur les cartes de l'Ordre, {place} ne porte qu'une mention : « Ici rôde {name} ».",
