  "Diadem": "Diadème",
  "Traum": "Rêve",
  "Gedanken": "Pensées",
  "Heiltotem": "Totem de soin",
  "Ein eisiger Ring um den Boss friert ein, wer drinsteht. Raus aus dem Kreis!": "Un anneau glacé autour du boss gèle quiconque s'y trouve. Sors du cercle!",
  "Meteorregen": "Pluie de météores",
  "Brennende Felsen fallen vom Himmel. Die Kreise zeigen, wo sie einschlagen.": "Des rochers en flammes tombent du ciel. Les cercles montrent où ils vont s'écraser.",
  "Schockwellen": "Ondes de choc",
  "Der Boss stampft – Wellen rollen nach außen. Rolle durch die Welle oder bleib außer Reichweite.": "Le boss frappe le sol – des ondes déferlent vers l'extérieur. Roule à travers l'onde ou reste hors de portée.",
  "Tipp: Während du rollst, kann dich nichts treffen – rolle durch Wellen hindurch!": "Astuce : pendant une roulade, rien ne peut te toucher – roule à travers les ondes!",
  "Eine Bahn zeigt, wohin der Boss gleich stürmt. Geh zur Seite!": "Une trajectoire montre où le boss va charger. Écarte-toi!",
  "Beschwörung": "Invocation",
  "Aus Portalen kriechen Diener. Erledige sie, bevor es zu viele werden.": "Des sbires rampent hors des portails. Élimine-les avant qu'ils ne soient trop nombreux.",
  "Schutzschild": "Bouclier",
  "Ein Schild schluckt viel Schaden. Brich ihn – dann ist der Boss kurz benommen.": "Un bouclier absorbe beaucoup de dégâts. Brise-le – le boss sera brièvement étourdi.",
  "Tipp: Brich den Schild – dann ist der Boss ein paar Sekunden benommen.": "Astuce : brise le bouclier – le boss sera étourdi quelques secondes.",
  "Der Boss verschwindet und taucht am markierten Ort wieder auf – mit einem Schlag.": "Le boss disparaît et réapparaît à l'endroit marqué – en frappant.",
  "Giftwolken": "Nuages toxiques",
  "Giftblasen platzen und hinterlassen Wolken, die lange brennen.": "Des bulles de poison éclatent et laissent des nuages qui brûlent longtemps.",
  "Blitzschlag": "Foudre",
  "Ein Zeichen folgt dir und bleibt dann stehen – lauf weg, bevor der Blitz einschlägt.": "Un signe te suit puis s'immobilise – fuis avant que la foudre ne tombe.",
  "Tipp: Das Zeichen folgt dir – sobald es stehen bleibt, lauf weg!": "Astuce : le signe te suit – dès qu'il s'arrête, fuis!",
  "Atemstoß": "Souffle",
  "Ein Fächer vor dem Boss wird gleich in Feuer, Eis oder Gift getaucht. Geh hinter ihn oder zur Seite.": "Un cône devant le boss va être noyé de feu, de glace ou de poison. Passe derrière lui ou sur le côté.",
  "Todessprung": "Saut mortel",
  "Der Boss springt dorthin, wo du stehst. Der Schatten am Boden zeigt die Landung.": "Le boss bondit là où tu te tiens. L'ombre au sol montre où il va atterrir.",
  "Kugelring": "Anneau d'orbes",
  "Ein Ring aus Geschossen fliegt nach außen. Stell dich in eine Lücke.": "Un anneau de projectiles s'étend vers l'extérieur. Place-toi dans une brèche.",
  "Kreuzschnitt": "Croix tranchante",
  "Leuchtende Linien durch den Boss werden gleich zu Klingen. Weg von den Linien!": "Des lignes lumineuses traversant le boss vont devenir des lames. Écarte-toi des lignes!",
  "Erdspalten": "Failles",
  "Der Boden reißt vom Boss in deine Richtung auf. Geh aus der Spur.": "Le sol se fend du boss jusqu'à toi. Sors de la trajectoire.",
  "Klingenwirbel": "Tourbillon de lames",
  "Klingen kreisen um den Boss. Erst sind sie blass – dann schneiden sie.": "Des lames tournoient autour du boss. D'abord pâles – puis tranchantes.",
  "Ein ganzes Feld fängt Feuer. Verlass die markierte Fläche schnell.": "Toute une zone s'embrase. Quitte vite la surface marquée.",
  "Lebensraub": "Vol de vie",
  "Im Kreis um den Boss saugt er dir Leben aus und heilt sich. Verlass den Kreis.": "Dans le cercle qui l'entoure, le boss aspire ta vie et se soigne. Quitte le cercle.",
  "Tipp: Verlass den roten Kreis, dann reißt der Lebensraub ab.": "Astuce : quitte le cercle rouge pour rompre le vol de vie.",
  "Unter 30 % Leben wird der Boss schneller und stärker.": "Sous 30 % de vie, le boss devient plus rapide et plus fort.",
  "Phasen": "Phases",
  "Bei 66 % und 33 % Leben stößt der Boss alle zurück und kämpft danach schneller – manchmal mit neuen Kräften.": "À 66 % et 33 % de vie, le boss repousse tout le monde, puis se bat plus vite – parfois avec de nouveaux pouvoirs.",
  "Seelenjäger": "Chasseurs d'âmes",
  "Langsame Geister verfolgen dich. Weiche aus oder zerschlag sie mit Nahkampfhieben.": "Des esprits lents te poursuivent. Esquive-les ou détruis-les au corps à corps.",
  "Sprengsaat": "Semis explosif",
  "Der Boss verstreut Minen. Kommst du zu nah, zünden sie – der rote Kreis zeigt die Explosion.": "Le boss sème des mines. Approche-toi trop et elles sautent – le cercle rouge montre l'explosion.",
  "Der Boss heilt sich. Viel Schaden in kurzer Zeit unterbricht ihn.": "Le boss se soigne. Beaucoup de dégâts en peu de temps l'interrompent.",
  "Tipp: Viel Schaden in kurzer Zeit unterbricht die Heilung.": "Astuce : beaucoup de dégâts en peu de temps interrompent le soin.",
  "Heiltotems": "Totems de soin",
  "Totems heilen den Boss, solange sie stehen. Zerstöre sie zuerst.": "Les totems soignent le boss tant qu'ils sont debout. Détruis-les en premier.",
  "Tipp: Die Totems heilen den Boss – zerstöre sie zuerst!": "Astuce : les totems soignent le boss – détruis-les en premier!",
  "Sog": "Aspiration",
  "Der Boss zieht dich zu sich – in seiner Mitte wartet Schaden. Lauf dagegen an.": "Le boss t'attire à lui – en son centre, des dégâts t'attendent. Cours dans l'autre sens.",
  "Kugelspirale": "Spirale d'orbes",
  "Drehende Arme aus Geschossen. Bewege dich mit der Drehung.": "Des bras de projectiles qui tournoient. Déplace-toi dans le sens de la rotation.",
  "Blitze springen zwischen Punkten um dich herum. Stell dich nicht auf eine Linie.": "Des éclairs bondissent entre des points autour de toi. Ne reste pas sur une ligne.",
  "Spiegelbilder": "Reflets",
  "Trugbilder des Bosses erscheinen. Nur der echte leuchtet und hat den Lebensbalken oben.": "Des illusions du boss apparaissent. Seul le vrai brille et possède la barre de vie en haut.",
  "Tipp: Nur der echte Boss hat den leuchtenden Rand – die Trugbilder zerfallen schnell.": "Astuce : seul le vrai boss a le contour lumineux – les illusions se dissipent vite.",
  "Todesstrahl": "Rayon mortel",
  "Eine dünne Linie zeigt den Strahl an – dann dreht er sich durch die Arena. Bleib hinter ihm.": "Une fine ligne annonce le rayon – puis il balaie l'arène en tournant. Reste derrière lui.",
  "Finsternis": "Ténèbres",
  "Alle Lichter erlöschen für ein paar Sekunden. Gefahren leuchten trotzdem.": "Toutes les lumières s'éteignent quelques secondes. Les dangers restent visibles.",
  "Tipp: Farbige Flächen zeigen, wo gleich Schaden kommt. Raus da, bevor sie aufleuchten!": "Astuce : les zones colorées montrent où les dégâts vont tomber. Sors-en avant qu'elles s'illuminent!",
  "Mutiges Herz": "Cœur vaillant",
  "Schrecken der Höhlen": "Terreur des antres",
  "Geißel der Ungeheuer": "Fléau des monstres",
  "Hammer der Bosse": "Marteau des boss",
