  "Albtraum der Tyrannen": "Cauchemar des tyrans",
  "Stern der Jagd": "Étoile de la chasse",
  "Erbe des Ordens": "Relève de l'Ordre",
  "Sturm der Tausend": "Tempête des Mille",
