  "BESIEGT": "VAINCU",
  "{name} war diesmal stärker. Im Boss-Kodex stehen alle Mechaniken – Übung macht den Meister.": "Cette fois, la victoire revient à {name}. Le Codex des boss détaille toutes les mécaniques – c'est en forgeant qu'on devient forgeron.",
  "Nochmal": "Rejouer",
