  "Alle Trophäen-Boni freigeschaltet!": "Tous les bonus de trophées débloqués!",
  "Unbekannter Boss, Rang {n}": "Boss inconnu, rang {n}",
  "Tippe einen Boss an. Unbekannte zeigen nur ihren Schatten – finde ihre Höhlen in den Endlosen Landen.": "Touche un boss. Les inconnus ne montrent que leur silhouette – trouve leurs antres dans les Terres Infinies.",
