  "Rune des Glücks": "Rune de fortune",
  "Kettenglyphe": "Glyphe de chaîne",
  "Frostglyphe": "Glyphe de givre",
  "Lebensglyphe": "Glyphe de vie",
  "Geisterglyphe": "Glyphe spectral",
  "Blutglyphe": "Glyphe de sang",
  "Sprengglyphe": "Glyphe explosif",
  "Sternglyphe": "Glyphe stellaire",
  "Schattenglyphe": "Glyphe d'ombre",
  "Vergeltungsglyphe": "Glyphe de représailles",
  "Wirbelglyphe": "Glyphe tourbillon",
  "Feueressenz": "Essence de feu",
  "Frostessenz": "Essence de givre",
  "Blitzessenz": "Essence de foudre",
  "Giftessenz": "Essence de poison",
  "Lichtessenz": "Essence de lumière",
  "Schattenessenz": "Essence d'ombre",
  "Salvenkern": "Noyau de salve",
  "Geschoss-Fähigkeiten": "Compétences à projectiles",
  "Weitenkern": "Noyau d'ampleur",
  "Flächen-Fähigkeiten": "Compétences de zone",
  "Wuchtkern": "Noyau d'impact",
  "Sprungkern": "Noyau de bond",
  "Bewegungs-Fähigkeiten": "Compétences de mouvement",
  "Bundkern": "Noyau d'alliance",
  "Schutz- und Helfer-Fähigkeiten": "Compétences de protection et d'alliés",
  "Flusskern": "Noyau de flux",
  "alle Fähigkeiten": "toutes les compétences",
  "Zornkern": "Noyau de fureur",
  "Ultimative": "Ultime",
  "Goldprägung": "Empreinte d'or",
  "Glutprägung": "Empreinte de braise",
  "Eisprägung": "Empreinte de glace",
  "Smaragdprägung": "Empreinte d'émeraude",
  "Nachtprägung": "Empreinte de nuit",
  "Sternprägung": "Empreinte d'étoile",
  "EP +{v}": "XP +{v}",
  "Affix-Essenz {t}: {aff}": "Essence d'affixe {t} : {aff}",
  "{mod} {t}": "{mod} {t}",
  "Mod gefunden: {mod}": "Mod trouvé : {mod}",
  "Dein erster Mod! Setz ihn an einer Werkbank oder in der Schmiede ein: VERBESSERN → MODS.": "Ton premier mod! Insère-le à un établi ou à la forge : RENFORCER → MODS.",
  "{n} G": "{n} or",
  "{p} je Treffer: Kettenblitz auf {n} Gegner, je {v} Waffenschaden": "{p} par coup : éclair en chaîne sur {n} ennemis, {v} des dégâts de l'arme chacun",
  "{p} je Treffer: Frostnova um das Ziel ({v} Waffenschaden), friert {s} s ein": "{p} par coup : nova de givre autour de la cible ({v} des dégâts de l'arme), gèle {s} s",
  "Jeder Kill heilt {v} deiner LP": "Chaque kill rend {v} de tes PV",
  "{p} je Kill: ein Geist kämpft {s} s mit": "{p} par kill : un esprit combat à tes côtés pendant {s} s",
  "{p} je Treffer: Blutung, 4 s lang je Sekunde {v} Waffenschaden": "{p} par coup : saignement, {v} des dégâts de l'arme par seconde pendant 4 s",
  "{p} je Kill: der Gegner explodiert ({v} Waffenschaden ringsum)": "{p} par kill : l'ennemi explose ({v} des dégâts de l'arme alentour)",
  "{p} je kritischem Treffer: ein Meteor schlägt ein ({v} Waffenschaden)": "{p} par coup critique : un météore s'abat ({v} des dégâts de l'arme)",
  "{p} je Treffer: eine Schattenklinge trifft noch einmal ({v} Waffenschaden)": "{p} par coup : une lame d'ombre frappe une seconde fois ({v} des dégâts de l'arme)",
  "Wirst du getroffen: Druckwelle mit {v} Waffenschaden, höchstens alle {s} s": "Si on te touche : onde de choc de {v} des dégâts de l'arme, au plus toutes les {s} s",
  "{p} je kritischem Treffer: Klingenwirbel um dich, 1,4 s lang je {v} Waffenschaden": "{p} par coup critique : tourbillon de lames autour de toi, {v} des dégâts de l'arme par touche pendant 1,4 s",
  "Fächerschuss: Pfeile +{n}": "Tir en éventail : flèches +{n}",
  "Giftklingen: Messer +{n}": "Lames empoisonnées : couteaux +{n}",
  "Kettenblitz: Sprünge +{n}": "Éclair en chaîne : rebonds +{n}",
  "Feuerball +{v} Schaden und ein zweiter Feuerball": "Boule de feu +{v} de dégâts et une seconde boule de feu",
  "Feuerball +{v} Schaden": "Boule de feu +{v} de dégâts",
  "Pfeilsturm: Pfeile je Salve +{n}": "Tempête de flèches : flèches par salve +{n}",
  "{skills}: Radius +{v}": "{skills} : rayon +{v}",
  "{skills}: Schaden +{v}": "{skills} : dégâts +{v}",
  "{skills}: Abklingzeit −{c}, Schaden +{v}": "{skills} : recharge −{c}, dégâts +{v}",
  "{skill} +{n} s": "{skill} +{n} s",
  "Fähigkeiten kosten {v} weniger": "Compétences {v} moins chères",
