  "Keine Affix-Essenz für Rüstung und Helm. Du bekommst welche unter EXTRAHIEREN – aus einer anderen Rüstung oder einem Helm.": "Aucune essence d'affixe pour armure et casque. Tu en obtiens via EXTRAIRE – à partir d'une autre armure ou d'un casque.",
