  "Bestimmte Mods zusammen wecken eine neue Kraft – auf einem Gegenstand oder über die ganze Ausrüstung. Unentdeckte zeigen einen Hinweis.": "Certains mods réunis éveillent un nouveau pouvoir – sur un objet ou sur tout l'équipement. Celles qui restent à découvrir affichent un indice.",
