  "Seil": "Corde",
  "Ein Kletterseil mit Wurfhaken – damit kommst du an den Übergängen über Schluchten.": "Une corde d'escalade avec grappin – grâce à elle, tu franchis les gouffres aux passages.",
  "Brückenstein": "Pierre des ponts",
  "Ein Stein der Alten: Er lässt eingestürzte Brücken über reißende Flüsse wieder erstehen.": "Une pierre des Anciens : elle relève les ponts effondrés au-dessus des fleuves déchaînés.",
  "Kräutermaske": "Masque d'herbes",
  "Filtert Giftnebel und Giftluft. Ohne sie brennt jeder Atemzug.": "Filtre la brume toxique et l'air empoisonné. Sans lui, chaque inspiration te brûle.",
  "Eishaken": "Piolet",
  "Steigeisen und Haken: Damit erklimmst du Eisklippen an den markierten Stellen.": "Crampons et crochets : avec eux, tu escalades les falaises de glace aux endroits marqués.",
  "Feuermantel": "Manteau de feu",
  "Schützt vor Lava, Hitze und eisiger Kälte. Über Lavaströme führen Trittsteine.": "Protège de la lave, de la chaleur et du froid glacial. Des pierres de gué permettent de traverser les coulées de lave.",
  "Schattenlaterne": "Lanterne des ombres",
  "Ihr Licht durchdringt die lebendige Finsternis und vertreibt die Dunkelheit.": "Sa lumière perce les ténèbres vivantes et chasse l'obscurité.",
  "Gezeitenperle": "Perle des marées",
  "Teilt die Fluten: An den Pfeilern der Alten trägt dich das Wasser.": "Fend les flots : aux piliers des Anciens, l'eau te porte.",
  "Dornenklinge": "Lame d'épines",
  "Schneidet Wege durch Dornenwälle, die nichts anderes durchdringt.": "Taille un chemin à travers les murs d'épines que rien d'autre ne peut percer.",
  "Sturmfeder": "Plume de tempête",
  "Hält dich im Auge des Sturms – Sturmwände und Böen werfen dich nicht mehr zurück.": "Te garde dans l'œil du cyclone – murs de tempête et bourrasques ne te repoussent plus.",
  "Sternenschlüssel": "Clé des étoiles",
  "Öffnet die uralten Siegel der Sternentore.": "Ouvre les sceaux antiques des portails stellaires.",
  "Leere-Anker": "Ancre du Néant",
  "Verankert dich in der Wirklichkeit – über Leere-Risse und durch das Nichts.": "T'ancre dans la réalité – par-delà les failles du Néant et à travers le vide.",
  "Seil II": "Corde II",
  "Ein Seil aus Sternenfaden mit Kristallhaken – es hält auch über der Kristallkluft, wo jedes andere Seil zerschneidet.": "Une corde en fil d'étoile munie de crochets de cristal – elle tient même au-dessus de l'abîme de cristal, là où toute autre corde se fait trancher.",
  "Kräutermaske II": "Masque d'herbes II",
  "Gefüllt mit Kräutern vom Rand der Welt: Sie filtert die Wand aus Blutnebel, den Blutdunst der Sümpfe und die Sporenluft der Pilzriesen.": "Garni d'herbes du bout du monde : il filtre le mur de brume sanglante, les vapeurs de sang des marais et la nuée de spores des Champignons géants.",
  "Eishaken II": "Piolet II",
  "Haken aus Himmelsstahl: Damit kletterst du am Himmelsabbruch entlang, und kein Höhensturm reißt dich fort.": "Un piolet en acier céleste : grâce à lui, tu escalades l'à-pic céleste, et aucune tempête d'altitude ne peut t'emporter.",
  "Brückenstein II": "Pierre des ponts II",
  "Ein Stein der Alten, der Brücken über den Seelenstrom baut. Sein Licht hält auch den Seelensog von dir fern.": "Une pierre des Anciens qui bâtit des ponts au-dessus du torrent des âmes. Sa lumière tient aussi l'aspiration des âmes à distance.",
  "Feuermantel II": "Manteau de feu II",
  "Gewebt aus Sternenfeuer: schützt vor Sternenglut und Grabeskälte. Über die Glutströme führen schwebende Steine.": "Tissé de feu stellaire : protège de la braise stellaire et du froid sépulcral. Des pierres flottantes permettent de traverser les torrents de braise.",
  "Schattenlaterne II": "Lanterne des ombres II",
  "Ihr Licht weckt dich aus jedem Traum: Sie zerreißt den Traumschleier und vertreibt den Traumnebel.": "Sa lumière t'arrache à tous les rêves : elle déchire le voile des rêves et dissipe la brume onirique.",
  "Gezeitenperle II": "Perle des marées II",
  "Eine Perle aus erstarrter Zeit: An den Stundenpfeilern hält sie den Zeitstrom an und schützt vor dem Zeitsog.": "Une perle de temps figé : aux piliers des heures, elle arrête le flux temporel et te protège du remous temporel.",
  "Dornenklinge II": "Lame d'épines II",
  "Geschmiedet aus Sternensplittern: Sie schneidet Wege durch Splitterwälle und zerschlägt den Splitterregen.": "Forgée dans des éclats d'étoiles : elle taille des passages à travers les murs d'éclats et brise la pluie d'éclats.",
  "Sternenschlüssel II": "Clé des étoiles II",
  "Der Schlüssel zum Siegel der Welt. Dahinter liegt nur noch der Weltenrand – und das Ende der Welt.": "La clé du Sceau du monde. Au-delà, il n'y a plus que les Confins du monde – et le Bout du monde.",
  "Schlucht": "Gouffre",
  "Reißender Fluss": "Fleuve déchaîné",
  "Eisklippen": "Falaises de glace",
  "Lavastrom": "Coulée de lave",
