  "Himmelsabbruch": "À-pic céleste",
  "Seelenstrom": "Torrent des âmes",
  "Sternenglut": "Braise stellaire",
  "Traumschleier": "Voile des rêves",
  "Zeitstrom": "Flux temporel",
  "Splitterwall": "Mur d'éclats",
  "Siegel der Welt": "Sceau du monde",
  "Giftluft": "Air toxique",
  "Giftluft! Ohne Kräutermaske brennt jeder Atemzug.": "Air toxique! Sans masque d'herbes, chaque inspiration te brûle.",
  "Eisige Kälte": "Froid glacial",
  "Eisige Kälte! Ohne Feuermantel wirst du langsam und frierst.": "Froid glacial! Sans manteau de feu, tu ralentis et tu gèles.",
  "Glühende Hitze": "Chaleur ardente",
  "Glühende Hitze! Ohne Feuermantel versengt sie dich.": "Chaleur ardente! Sans manteau de feu, elle te consume.",
  "Finsternis! Ohne Schattenlaterne siehst du kaum die Hand vor Augen.": "Ténèbres! Sans lanterne des ombres, tu ne vois pas plus loin que le bout de ton nez.",
  "Sturm": "Tempête",
  "Sturm! Ohne Sturmfeder werfen dich die Böen umher.": "Tempête! Sans plume de tempête, les bourrasques te ballottent.",
  "Sog der Leere": "Aspiration du Néant",
  "Die Leere saugt an deiner Kraft! Ohne Leere-Anker schwindet sie.": "Le Néant aspire tes forces! Sans ancre du Néant, elles s'épuisent.",
  "Blutdunst": "Vapeurs de sang",
  "Blutdunst! Ohne Kräutermaske II saugt er dir das Leben aus.": "Vapeurs de sang! Sans masque d'herbes II, elles aspirent ta vie.",
  "Sporenluft": "Nuée de spores",
  "Sporenluft! Ohne Kräutermaske II vergiftet sie dich.": "Nuée de spores! Sans masque d'herbes II, elle t'empoisonne.",
  "Höhensturm": "Tempête d'altitude",
  "Höhensturm! Ohne Eishaken II reißt er dich von den Füßen.": "Tempête d'altitude! Sans piolet II, elle te fait perdre pied.",
  "Seelensog": "Aspiration des âmes",
  "Seelensog! Ohne Brückenstein II zehren die Seelen an Kraft und Leben.": "Aspiration des âmes! Sans pierre des ponts II, les âmes rongent ta force et ta vie.",
  "Sternenglut! Ohne Feuermantel II verbrennst du.": "Braise stellaire! Sans manteau de feu II, tu brûles.",
  "Grabeskälte": "Froid sépulcral",
  "Grabeskälte! Ohne Feuermantel II erstarrst du.": "Froid sépulcral! Sans manteau de feu II, tu te figes.",
  "Traumnebel": "Brume onirique",
  "Traumnebel! Ohne Schattenlaterne II wirst du müde und siehst kaum etwas.": "Brume onirique! Sans lanterne des ombres II, tu t'assoupis et ne vois presque rien.",
  "Zeitsog": "Remous temporel",
  "Zeitsog! Ohne Gezeitenperle II zerrt die Zeit an dir.": "Remous temporel! Sans perle des marées II, le temps te tiraille.",
  "Splitterregen": "Pluie d'éclats",
  "Splitterregen! Ohne Dornenklinge II schneiden dich die Splitter.": "Pluie d'éclats! Sans lame d'épines II, les éclats te lacèrent.",
