  "Bald bricht die Nacht herein – dann streifen mehr und stärkere Gegner umher.": "Bientôt, la nuit tombera – des ennemis plus nombreux et plus forts rôderont alors.",
  "NACHT": "NUIT",
  "DIE NACHT BRICHT AN": "LA NUIT TOMBE",
  "Jäger der Nacht sind unterwegs. Halte ein Tor oder Leuchtfeuer im Blick!": "Les chasseurs de la nuit rôdent. Garde un portail ou un fanal à portée!",
  "MORGEN": "AUBE",
  "DER MORGEN GRAUT": "LE JOUR SE LÈVE",
  "Die Jäger der Nacht ziehen sich zurück.": "Les chasseurs de la nuit battent en retraite.",
