  "Goldkönig": "Roi de l'or",
  "Legende des Basars": "Légende du bazar",
  "Auktionatorin Hedda": "Hedda la Crieuse",
  "Alles hat seinen Preis, {name}. Die Kunst ist, ihn vor den anderen zu kennen.": "Tout a un prix, {name}. Tout l'art est de le connaître avant les autres.",
  "Kaspar bietet immer in der letzten Minute. Halt die Augen offen.": "Kaspar enchérit toujours à la dernière minute. Garde l'œil ouvert.",
  "Wer versteigert, braucht Geduld. Wer bietet, braucht Nerven.": "Pour vendre aux enchères, il faut de la patience. Pour enchérir, des nerfs d'acier.",
  "Ein Legendärer unter Marktwert? Kommt vor. Selten. Aber es kommt vor.": "Un légendaire sous sa valeur marchande? Ça arrive. Rarement. Mais ça arrive.",
  "Grimbart sammelt alles, was glänzt – und zahlt dafür fast jeden Preis.": "Grimbart collectionne tout ce qui brille – et il paie presque n'importe quel prix pour ça.",
  "Mein Hammer fällt, wenn die Zeit um ist. Keine Sekunde früher.": "Mon marteau tombe quand le temps est écoulé. Pas une seconde plus tôt.",
  "Marktwert: {n} Gold": "Valeur marchande : {n} or",
  "Handelsrang {n}: {title}! Weniger Gebühr, mehr Plätze.": "Rang marchand {n} : {title}! Moins de commission, plus d'emplacements.",
  "Bauteil für die Schmiede": "Composant pour la forge",
  "Kommt in dein Brutnest. Gut gepflegt schlüpft daraus ein Begleiter.": "Va dans ton nid. Bien soigné, il donnera naissance à un compagnon.",
  "Marktwert: {n} Gold je Stück": "Valeur marchande : {n} or l'unité",
  "Zusammen: {n} Gold": "Total : {n} or",
