  "Wert {n}": "Valeur {n}",
  "Du wurdest überboten! {item}: {name} bietet {n} Gold.": "Offre dépassée! {item} : {name} propose {n} or.",
  "Zuschlag! {item} für {n} Gold ersteigert – im Abholfach.": "Adjugé! {item} remporté pour {n} or – dans le casier.",
  "Verkauft! {item} an {name} für {n} Gold.": "Vendu! {item} à {name} pour {n} or.",
  "Nicht verkauft: {item} – liegt im Abholfach.": "Invendu : {item} – dans le casier.",
  "Neues Gebot auf {item}: {n} Gold von {name}.": "Nouvelle offre sur {item} : {n} or de {name}.",
  "Versteigerung verloren: {item} ging für {n} Gold an {name}.": "Enchère perdue : {item} est parti à {name} pour {n} or.",
  "Basar: {n} weitere Neuigkeiten – siehe MEINE.": "Bazar : {n} autres nouvelles – voir À MOI.",
  "ZUSCHLAG!": "ADJUGÉ!",
  "VERKAUFT!": "VENDU!",
  "Zu wenig Gold.": "Pas assez d'or.",
  "Beutel und Lager sind voll. Mach zuerst Platz.": "Sac et entrepôt pleins. Fais d'abord de la place.",
  "Dein Brutnest ist voll.": "Ton nid est plein.",
  "Eier kann diese Version noch nicht annehmen.": "Cette version ne peut pas encore recevoir d'œufs.",
  "Das ist nicht mehr da.": "Ce n'est plus disponible.",
  "Diese Versteigerung ist schon vorbei.": "Cette enchère est déjà terminée.",
  "Du hast schon das höchste Gebot.": "Tu as déjà la meilleure offre.",
  "Das Gebot ist zu niedrig.": "L'offre est trop basse.",
  "Alle Auktionsplätze sind belegt. Ein höherer Handelsrang bringt mehr.": "Tous les emplacements d'enchère sont pris. Un rang marchand plus élevé en donne davantage.",
  "Wähle zuerst einen Helden.": "Choisis d'abord un héros.",
  "Es gibt schon Gebote – die Versteigerung läuft bis zum Ende.": "Il y a déjà des offres – l'enchère ira jusqu'au bout.",
  "{item} liegt im Beutel.": "{item} est dans ton sac.",
  "Beutel voll – {item} liegt im Lager.": "Sac plein – {item} est dans l'entrepôt.",
  "{item} liegt im Brutnest.": "{item} est dans ton nid.",
  "{item} liegt im Abholfach.": "{item} est dans le casier.",
  "{item} ist in deinem Vorrat.": "{item} est dans ta réserve.",
  "+{n} Gold aus dem Abholfach": "+{n} or du casier",
  "ABHOLFACH": "CASIER",
  "1 Sache wartet auf dich – antippen zum Abholen.": "1 objet t'attend – touche pour le récupérer.",
  "{n} Sachen warten auf dich – antippen zum Abholen.": "{n} objets t'attendent – touche pour les récupérer.",
  "Die Uhr deines Geräts wurde zurückgestellt. Der Basar wartet, bis sie wieder stimmt (noch {t}).": "L'horloge de ton appareil a été reculée. Le bazar attend qu'elle soit de nouveau juste (encore {t}).",
  "BASAR": "BAZAR",
  "BIETEN": "ENCHÉRIR",
  "MEINE": "À MOI",
  "SCHNÄPPCHEN": "PROMO",
  "noch {n}": "reste {n}",
  "AUSVERKAUFT": "ÉPUISÉ",
  "Tippe ein Angebot an, um es genau anzusehen. Gekauftes kommt in den Beutel – ist er voll, ins Lager.": "Touche un article pour le voir en détail. Tes achats vont dans le sac – s'il est plein, dans l'entrepôt.",
  "Kaufen": "Acheter",
  "Dir fehlen {n} Gold.": "Il te manque {n} or.",
  "Nächste Lieferung in {t}": "Prochain arrivage dans {t}",
  "Nur solange der Vorrat reicht.": "Dans la limite des stocks disponibles.",
  "GEGENSTÄNDE": "OBJETS",
  "MATERIAL": "MATÉRIAUX",
  "Sofort verkaufen bringt Gold auf die Hand. Versteigern bringt meist mehr – dauert aber.": "La vente immédiate te rapporte de l'or tout de suite. Les enchères rapportent souvent plus – mais prennent du temps.",
  "Sicher? {n} Gegenstände für {g} Gold": "Sûr? {n} objets pour {g} or",
  "Gewöhnliche & Magische sofort verkaufen ({g} Gold)": "Vendre communs & magiques ({g} or)",
  "je {n}": "{n} l'unité",
  "{n} Stück · Wert {v}": "Qté {n} · valeur {v}",
  "Wähle aus, was du loswerden willst. Angelegte Ausrüstung bleibt bei dir.": "Choisis ce dont tu veux te débarrasser. L'équipement porté reste avec toi.",
  "von {n}": "sur {n}",
  "Wirklich? Für": "Vraiment? Pour",
  "Sofort verkaufen": "Vente immédiate",
  "Versteigern …": "Aux enchères …",
  "VERSTEIGERN": "AUX ENCHÈRES",
  "Marktwert": "Valeur marchande",
  "STARTPREIS": "PRIX DE DÉPART",
  "Ein niedriger Start lockt mehr Bieter – mit wenigen Bietern bleibt der Preis aber niedrig.": "Un prix de départ bas attire plus d'enchérisseurs – mais avec peu d'enchérisseurs, le prix reste bas.",
  "SOFORTKAUF": "ACHAT IMMÉDIAT",
  "AUS": "NON",
  "DAUER": "DURÉE",
  "{n} STD.": "{n} H",
  "wenige": "peu",
  "viele": "beaucoup",
  "Verkaufschance etwa {p} % · üblicher Erlös {lo}–{hi} Gold (nach {fee} % Gebühr).": "Chance de vente : env. {p} % · gain habituel {lo}–{hi} or (après {fee} % de commission).",
  "So teuer will das wohl niemand – senk den Startpreis.": "Personne ne voudra payer aussi cher – baisse le prix de départ.",
  "Längere Versteigerungen finden mehr Bieter. Die Gebühr zahlst du nur, wenn verkauft wird. Unverkauftes kommt ins Abholfach zurück.": "Les enchères plus longues attirent plus d'enchérisseurs. Tu ne paies la commission qu'en cas de vente. Les invendus reviennent dans le casier.",
  "Versteigerung starten": "Lancer l'enchère",
  "Alle {n} Auktionsplätze belegt": "Les {n} emplacements sont pris",
  "Start {n} Gold · noch kein Gebot": "Départ {n} or · aucune offre",
  "DU FÜHRST": "EN TÊTE",
  "ÜBERBOTEN": "DÉPASSÉ",
  "VERLÄNGERT": "PROLONGÉ",
  "Sofort {n}": "Achat {n}",
  "Gerade läuft keine Versteigerung. Schau gleich noch mal vorbei.": "Aucune enchère en cours. Repasse dans un instant.",
  "Biete gegen andere Händler. Dein Gebot wird reserviert – wirst du überboten, bekommst du es zurück.": "Enchéris contre d'autres marchands. Ton offre est mise de côté – si quelqu'un te dépasse, tu la récupères.",
  "Tippe eine Versteigerung an, um zu bieten. Kurz vor Schluss wird oft noch geboten – dann verlängert sich die Zeit.": "Touche une enchère pour enchérir. Les offres tombent souvent juste avant la fin – le temps est alors prolongé.",
  "Dein Gebot: {n} Gold": "Ton offre : {n} or",
  "Höchstgebot {n} Gold von {name}": "Meilleure offre : {n} or de {name}",
  "Startpreis {n} Gold – noch kein Gebot": "Prix de départ {n} or – aucune offre",
  "Marktwert {n}": "Valeur marchande {n}",
  "Du führst! Bleib dran – kurz vor Schluss wird oft noch geboten.": "Tu es en tête! Reste attentif – les offres tombent souvent juste avant la fin.",
  "mind. {n}": "min. {n}",
  "Bieten": "Enchérir",
  "Wirklich? Sofortkauf": "Vraiment? Achat immédiat",
