  "Noch kein Gebot · Start {n} Gold": "Aucune offre · départ {n} or",
  "Noch nichts eingestellt. Wähle unter VERKAUFEN etwas aus und tippe „Versteigern“.": "Rien en vente pour l'instant. Choisis quelque chose dans VENDRE et touche « Aux enchères ».",
