  "Nächster Rang „{t}“: {f} % Gebühr, {s} Plätze, bessere Ware.": "Rang suivant « {t} » : {f} % de commission, {s} emplacements, meilleure marchandise.",
  "Jedes Gold, das du im Basar umsetzt, zählt. Verkauft: {s} · Gekauft: {b} · Bester Verkauf: {best} Gold": "Chaque pièce d'or échangée au bazar compte. Ventes : {s} · Achats : {b} · Meilleure vente : {best} or",
